import sys

def calculateTotalCost(arr, n):
    if n == 0:
        return 0
    return arr[n-1] + calculateTotalCost(arr, n-1)

def applyDiscount(totalCost, itemCount):
    if itemCount <= 0:
        return totalCost
    if itemCount <= 5:
        discount_rate = 0.05
    elif itemCount <= 10:
        discount_rate = 0.10
    else:
        discount_rate = 0.15
    return totalCost * (1 - discount_rate)

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    items = list(map(int, data[1:1+n]))
    total = calculateTotalCost(items, n)
    final = applyDiscount(total, n)
    print(f"{final:.2f}")

if __name__ == "__main__":
    main()
